node --test tests/visible.test.mjs && node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readLines, LineReader } from './src/lines.mjs';
const enc = new TextEncoder();
const splitEveryByte = (s) => Array.from(enc.encode(s), (byte) => Uint8Array.of(byte));
assert.deepEqual(await readLines(splitEveryByte('α\r\n\nx\ry\r\r\nend\r')), ['α', '', 'x\ry\r', 'end\r']);
assert.deepEqual(await readLines(splitEveryByte('a\n')), ['a']);
assert.deepEqual(await readLines([]), []);
const reader = new LineReader();
assert.deepEqual(reader.feed(Uint8Array.of(0xe2)), []);
assert.deepEqual(reader.feed(Uint8Array.of(0x82)), []);
assert.deepEqual(reader.feed(Uint8Array.of(0xac, 0x0a)), ['€']);
assert.deepEqual(reader.end(), []);
const invalid = await readLines([Uint8Array.of(0xe2), Uint8Array.of(0x28, 0xa1)]);
assert.deepEqual(invalid, [new TextDecoder().decode(Uint8Array.of(0xe2, 0x28, 0xa1))]);
console.log('Additional streaming UTF-8 and line-ending checks passed.');
NODE

